svg.script:
(async()=>{
 const el=document.getElementById('out');
 try{
  const r=await fetch('http://127.0.0.1:10789/api/v1/tools/call',{
   method:'POST',
   headers:{'Content-Type':'application/json'},
   body:JSON.stringify({name:'automation_safety',arguments:{operation:'status'}})
  });
  const t=await r.text();
  document.title='CUA_SVG_'+r.status;
  el.textContent='HTTP '+r.status+' '+t.slice(0,500);
 }catch(e){
  document.title='CUA_SVG_ERR';
  el.textContent='ERR '+String(e);
 }
})();
